const s = createScene3D({ span: 8 });
s.grid();
s.axes();

const g = 9.8;
const vx = 3, vy = 6, vz = 2;
const x0 = -4, y0 = 0, z0 = -2;

// trace full parabolic path first (dim, static preview)
s.curve3d((t) => {
  const time = t * 1.6;
  return [x0 + vx*time, y0 + vy*time - 0.5*g*time*time, z0 + vz*time];
}, { t0: 0, t1: 1, color: "#94a3b8" });

s.label("launch", { x: x0, y: y0 + 0.6, z: z0, color: "#22c55e" });
s.label("landing", { x: x0 + vx*1.6, y: 0.6, z: z0 + vz*1.6, color: "#ef4444" });

const ball = s.sphere({ x: x0, y: y0, z: z0, r: 0.35, color: "#f59e0b" });

s.tween(ball.position, {
  x: (t) => x0 + vx * (t * 1.6),
  y: (t) => Math.max(0, y0 + vy*(t*1.6) - 0.5*g*(t*1.6)*(t*1.6)),
  z: (t) => z0 + vz * (t * 1.6),
}, 6, { easing: "linear" });

s.label("gravity pulls y down", { x: 0, y: 4, z: 0, color: "#60a5fa" });
const g_arrow = s.arrow({ from: [0, 4.5, 0], to: [0, 3.5, 0], color: "#60a5fa" });

const s = createScene3D({ span: 6 });
s.grid();
const sun = s.sphere({ x: 0, y: 0, z: 0, r: 0.7, color: "#fbbf24" });
s.label("Sun", { x: 0, y: 1.1, z: 0, color: "#fbbf24" });

const planet = s.sphere({ r: 0.28, color: "#3b82f6" });
s.label("Planet", { x: 4.2, y: 0.6, z: 0, color: "#3b82f6" });

// Elliptical orbit, focus at Sun (offset center)
const a = 4, b = 2.5, c = Math.sqrt(a * a - b * b);

// Non-uniform speed profile: faster near perihelion, slower at aphelion
// Use eased angle progression via a warped time function
function angleAt(t) {
  // t in [0,1): warp so planet spends more "t" near aphelion
  const theta = 2 * Math.PI * t;
  return theta - 0.5 * Math.sin(theta); // Kepler-like speed variation
}

s.tween(planet.position, {
  x: (t) => a * Math.cos(angleAt(t)) - c,
  z: (t) => b * Math.sin(angleAt(t)),
  y: (t) => 0,
}, 8, { easing: "linear" });

// Draw the elliptical path
s.curve3d((t) => {
  const theta = 2 * Math.PI * t;
  return [a * Math.cos(theta) - c, 0, b * Math.sin(theta)];
}, { t0: 0, t1: 1, color: "#94a3b8", progress: 1 });

s.label("Perihelion (fast)", { x: a - c, y: 0.6, z: 0, size: 0.35, color: "#22c55e" });
s.label("Aphelion (slow)", { x: -a - c, y: 0.6, z: 0, size: 0.35, color: "#ef4444" });

const s = createScene3D({ span: 6 });
s.axes();
s.grid();

const r = 1.5;
const L = 6; // wave length along z (time axis)

// static circle guide
s.curve3d((t) => [r*Math.cos(t*2*Math.PI), r*Math.sin(t*2*Math.PI), 0],
  { t0: 0, t1: 1, color: "#94a3b8", progress: 1 });

const orbitDot = s.sphere({ r: 0.15, color: "#3b82f6" });
const waveDot = s.sphere({ r: 0.15, color: "#f97316" });

// sine wave, drawn progressively
const wave = s.curve3d((t) => [0, r*Math.sin(t*2*Math.PI), t*L],
  { t0: 0, t1: 1, color: "#f97316", progress: 0 });

// connecting line showing the "projection" from circle to wave
const link = s.arrow({ from: [r, 0, 0], to: [0, 0, 0], color: "#cbd5e1" });

const dur = 6;
s.tween(orbitDot.position, {
  x: (t) => r*Math.cos(t*2*Math.PI),
  y: (t) => r*Math.sin(t*2*Math.PI),
  z: 0
}, dur, { easing: "linear" });

s.tween(waveDot.position, {
  x: 0,
  y: (t) => r*Math.sin(t*2*Math.PI),
  z: (t) => t*L
}, dur, { easing: "linear" });

s.tween(link.from, {
  x: (t) => r*Math.cos(t*2*Math.PI),
  y: (t) => r*Math.sin(t*2*Math.PI),
  z: 0
}, dur, { easing: "linear" });

s.tween(link.to, {
  x: 0,
  y: (t) => r*Math.sin(t*2*Math.PI),
  z: (t) => t*L
}, dur, { easing: "linear" });

s.tween(wave, { progress: [0, 1] }, dur, { easing: "linear" });

s.label("circular motion", { x: 0, y: r + 0.6, z: -0.3, color: "#3b82f6" });
s.label("y = sin(θ)", { x: 0, y: r + 0.6, z: L, color: "#f97316" });

const s = createScene3D({ span: 5 });
s.grid();

const pivot = { x: 0, y: 3, z: 0 };
s.label("pivot", { x: 0, y: 3.3, z: 0 });

const L = 2.5;
const thetaMax = Math.PI / 4;
const theta = (t) => thetaMax * Math.cos(t * 4 * Math.PI);

const rod = s.arrow({
  from: [pivot.x, pivot.y, pivot.z],
  to: [L * Math.sin(theta(0)), pivot.y - L * Math.cos(theta(0)), 0],
  color: "#94a3b8",
});

const bob = s.sphere({
  x: L * Math.sin(theta(0)),
  y: pivot.y - L * Math.cos(theta(0)),
  z: 0,
  r: 0.3,
  color: "#ef4444",
});
s.label("bob", { x: 0.9, y: pivot.y - L, z: 0 });

s.arrow({ from: [2, 0.6, 0], to: [2, -0.2, 0], color: "#22c55e" });
s.label("gravity", { x: 2.3, y: 0.2, z: 0 });

s.label("equilibrium", { x: 0, y: pivot.y - L - 0.5, z: 0, color: "#94a3b8" });

s.tween(bob.position, {
  x: (t) => L * Math.sin(theta(t)),
  y: (t) => pivot.y - L * Math.cos(theta(t)),
}, 8, { easing: "linear" });

s.tween(rod.to, {
  x: (t) => L * Math.sin(theta(t)),
  y: (t) => pivot.y - L * Math.cos(theta(t)),
}, 8, { easing: "linear" });

const s = createScene3D({ span: 6 });
s.axes();
s.grid();

s.label("f(x, z) = sin(x)·cos(z)", { x: 0, y: 3.2, z: 0, size: 0.4 });
s.label("x", { x: 5.5, y: 0, z: 0 });
s.label("height = output", { x: 0, y: 2.2, z: -4.5 });

const surf = s.surface(
  (x, z) => 1.5 * Math.sin(x) * Math.cos(z),
  { xmin: -5, xmax: 5, zmin: -5, zmax: 5, color: "#22c55e", opacity: 0.0 }
);

// fade the surface in to feel like it "appears"
s.tween(surf.material, { opacity: [0, 0.85] }, 2.5);

// a marker ball that walks along the surface tracing a path
const marker = s.sphere({ r: 0.15, color: "#f97316" });
s.tween(marker.position, {
  x: (t) => 4 * Math.cos(t * 2 * Math.PI),
  z: (t) => 4 * Math.sin(t * 2 * Math.PI),
  y: (t) => {
    const x = 4 * Math.cos(t * 2 * Math.PI);
    const z = 4 * Math.sin(t * 2 * Math.PI);
    return 1.5 * Math.sin(x) * Math.cos(z) + 0.1;
  }
}, 6, { delay: 2.5, easing: "linear" });

s.label("marker traces the surface height", { x: 0, y: -3, z: 0, size: 0.35 });

const s = createScene3D({ span: 6 });
s.grid();

const src1 = { x: -2, z: 0 };
const src2 = { x: 2, z: 0 };
s.sphere({ x: src1.x, y: 0.3, z: src1.z, r: 0.15, color: "#f97316" });
s.sphere({ x: src2.x, y: 0.3, z: src2.z, r: 0.15, color: "#3b82f6" });
s.label("Source 1", { x: src1.x, y: 1, z: src1.z, color: "#f97316" });
s.label("Source 2", { x: src2.x, y: 1, z: src2.z, color: "#3b82f6" });
s.label("Wave Interference", { x: 0, y: 3, z: 0, size: 0.5 });

const k = 2.5;
const speed = 6;

function heightAt(x, z, t) {
  const r1 = Math.hypot(x - src1.x, z - src1.z) + 0.001;
  const r2 = Math.hypot(x - src2.x, z - src2.z) + 0.001;
  const w1 = Math.sin(k * r1 - speed * t) / (1 + r1 * 0.3);
  const w2 = Math.sin(k * r2 - speed * t) / (1 + r2 * 0.3);
  return 0.7 * (w1 + w2);
}

let time = 0;
const surf = s.surface((x, z) => heightAt(x, z, time), {
  xmin: -5, xmax: 5, zmin: -5, zmax: 5, color: "#22d3ee", opacity: 0.9
});

s.tween({ t: 0 }, { t: (t) => t }, 7, {
  easing: "linear"
});

s.tween(surf.position, { y: (t) => { time = t * 4; return 0; } }, 7, { easing: "linear" });
